class CosmosQuery
{
    void FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";
        // Also uses sync APIs
        var products = ctx.Products.Where(p => p.Sku == "ABC").ToList();
    }
}

arguments.new_str:
class CosmosQuery
{
    // EF Core 9 breaking change #3: Sync APIs (ToList, First, etc.) now throw by default.
    // Migrate to async; the sync query below is preserved only as a reference.
    async Task FindProductsAsync(ProductContext ctx)
    {
        // Direct Cosmos SQL — still works because we kept "Discriminator" property name.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        // Preferred: use async APIs in EF Core 9+
        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

